#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    long long maximumCalories(vector<int>& heights) {
        vector<int> h = heights;
        sort(h.begin(), h.end());
        int n = h.size();
        vector<int> seq = {0};
        int l = 0, r = n - 1;
        bool turn = true;
        while (l <= r) {
            if (turn) {
                seq.push_back(h[r--]);
            } else {
                seq.push_back(h[l++]);
            }
            turn = !turn;
        }
        long long total = 0;
        for (size_t i = 0; i < seq.size() - 1; ++i) {
            long long diff = seq[i + 1] - seq[i];
            total += diff * diff;
        }
        return total;
    }
};

import java.util.*;

class Solution {
    public long maximumCalories(int[] heights) {
        int[] h = heights.clone();
        Arrays.sort(h);
        int n = h.length;
        List<Integer> seq = new ArrayList<>();
        seq.add(0);
        int l = 0, r = n - 1;
        boolean turn = true;
        while (l <= r) {
            if (turn) {
                seq.add(h[r--]);
            } else {
                seq.add(h[l++]);
            }
            turn = !turn;
        }
        long total = 0;
        for (int i = 0; i < seq.size() - 1; i++) {
            long diff = seq.get(i + 1) - seq.get(i);
            total += diff * diff;
        }
        return total;
    }
}

